// Validate selections against item totals, then build bulk UPSERT
const guest    = $('Validate Token').first().json;
const body     = $('Webhook').first().json.body || $('Webhook').first().json;
const sels     = body.selections || [];

if (!sels.length) {
  throw new Error('No selections provided');
}

// Build a bulk upsert using json_array_elements
// We pass a single JSON parameter containing all selections
const selJson = JSON.stringify(sels.map(s => ({
  item_id:  s.item_id,
  quantity: Math.max(0, parseInt(s.quantity, 10) || 0)
})));

return [{
  json: {
    guest_id:  guest.guest_id,
    party_id:  guest.party_id,
    sel_json:  selJson
  }
}];

// Validate that claimed qtys don't exceed item totals
const itemRows  = $input.all().map(i => i.json);
const prepared  = $('Prepare Upsert').first().json;
const sels      = JSON.parse(prepared.sel_json);

const itemMap = {};
itemRows.forEach(r => {
  itemMap[r.id] = { total: Number(r.total_quantity), othersClaimed: Number(r.others_claimed) };
});

for (const sel of sels) {
  const info = itemMap[sel.item_id];
  if (!info) continue; // item not in this party
  const available = info.total - info.othersClaimed;
  if (sel.quantity > available) {
    throw new Error(`Cannot claim ${sel.quantity} of item ${sel.item_id}; only ${available} available`);
  }
}

return [{ json: prepared }];
